mapper.select:
select
	id as id,
	title as title,
	business_type as businessType,
	method as method,
	request_method as requestMethod,
	oper_name as operName,
	if(oper_name = 'admin', '系统管理员', (select FULLNAME from uum_userinfo uu where uu.USERID = oper_name)) as username,
	dept_name as deptName,
	oper_ip as operIp,
	oper_param as operParam,
	json_result as jsonResult,
	status as status,
	error_msg as errorMsg,
	oper_time as operTime,
	oper_url as operUrl
from xuncha_base_log

	 and title = #{title}
	and ( business_type = 1 or business_type = 2)
	 and method = #{method}
	 and request_method = #{requestMethod}
	 and oper_name like concat('%', #{operName}, '%')
	 and dept_name like concat('%', #{deptName}, '%')
	 and oper_ip = #{operIp}
	 and oper_param = #{operParam}
	 and json_result = #{jsonResult}
	 and status = #{status}
	 and error_msg = #{errorMsg}
	 and oper_time = #{operTime}
	 and oper_url = #{operUrl}
	 and business_id = #{businessId}

mapper.update:
update xuncha_base_log
title = #{title}, business_type = #{businessType}, method = #{method}, request_method = #{requestMethod}, oper_name = #{operName}, dept_name = #{deptName}, oper_ip = #{operIp}, oper_param = #{operParam}, json_result = #{jsonResult}, status = #{status}, error_msg = #{errorMsg}, oper_time = #{operTime}, oper_url = #{operUrl},
where id = #{id}
